pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0xBEEF);

    function setUp() public {
        c = new C();
    }

    // fuzz the candidate lrtConfigAddr; reference should revert when addr == address(0), mutant will not
    function testFuzz_property(address lrtConfigAddr) public {
        // make sure caller is an admin in the sense of the test harness: the contract checks IAccessControl on lrtConfig
        // but the onlyLRTAdmin modifier checks hasRole on address(lrtConfig). Since during updateLRTConfig call this uses
        // the current lrtConfig value, which initially is zero (set in constructor), the onlyLRTAdmin would check hasRole on address(0).
        // To satisfy onlyLRTAdmin in the reference implementation we need to set lrtConfig to a contract that returns true for hasRole.
        // However updateLRTConfig itself is protected by onlyLRTAdmin. To allow calling updateLRTConfig in both reference and mutant,
        // we first set lrtConfig by calling initialize (which sets lrtConfig), so that onlyLRTAdmin will consult a nonzero contract.
        // Deploy a simple MockConfig that treats admin as having DEFAULT_ADMIN_ROLE.

        MockConfig cfg = new MockConfig(admin);
        // initialize c with cfg address to set lrtConfig and allow onlyLRTAdmin/onlyLRTManager checks to use cfg
        // initializer uses UtilLib.checkNonZeroAddress so cfg must be non-zero
        c.initialize(address(cfg));

        // now we must call updateLRTConfig as admin. onlyLRTAdmin checks IAccessControl(hasRole) on current lrtConfig (cfg)
        // so we impersonate admin
        vm.prank(admin);

        bool ok;
        try c.updateLRTConfig(lrtConfigAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: calling updateLRTConfig with address(0) must revert on the reference (because UtilLib.checkNonZeroAddress prevents zero),
        // so ok must be false when lrtConfigAddr == address(0). For all other addresses the call should succeed (ok == true).
        if (lrtConfigAddr == address(0)) {
            assertTrue(!ok, "reference: updateLRTConfig should revert for zero address");
        } else {
            assertTrue(ok, "reference: updateLRTConfig should accept non-zero address");
        }
    }
}

// Minimal mock that implements hasRole to satisfy onlyLRTAdmin/onlyLRTManager checks
contract MockConfig {
    address public admin;
    constructor(address _admin) {
        admin = _admin;
    }
    // hasRole: return true if account == admin
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == admin;
    }
    // stub functions used by C
    function rsETH() external pure returns (address) { return address(0x100); }
    function getContract(bytes32) external pure returns (address) { return address(0x200); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
}

