pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We need an account that is recognized as LRT admin by the contract's lrtConfig.
    // Since C's onlyLRTAdmin checks IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
    // and in the real reference the initialize sets lrtConfig and updateLRTConfig requires the caller to already be admin.
    // For this fuzz test we will bypass role checks by deploying a benign mock ILRTConfig that reports
    // hasRole(DEFAULT_ADMIN_ROLE, caller) == true for any caller we want (we'll make the fuzzer supply the admin).

    // Minimal mock implementing only what's needed by C during initialize and onlyLRTAdmin check.
    contract MockLRTConfig {
        function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
        function rsETH() external pure returns (address) { return address(0); }
        function getContract(bytes32) external pure returns (address) { return address(0); }
        function isSupportedAsset(address) external pure returns (bool) { return true; }
        function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a = new address[](0); return a; }
        function assetStrategy(address) external pure returns (address) { return address(0); }
        function getLSTToken(bytes32) external pure returns (address) { return address(0); }
        function getRoleAdmin(bytes32) external pure returns (bytes32) { return bytes32(0); }
        function getAssetPrice(address) external pure returns (uint256) { return 1; }
        function getRSETHPrice() external pure returns (uint256) { return 1; }
        // make hasRole return true for DEFAULT_ADMIN_ROLE (0x00) when queried with our chosen admin
        address public admin;
        constructor(address _admin) { admin = _admin; }
        function hasRole(bytes32 role, address account) external view returns (bool) {
            if (role == bytes32(0)) return account == admin;
            return false;
        }
    }

    function setUp() public {
        c = new C();
    }

    // fuzzed param: admin address who will call updateLRTConfig; and the candidate lrtConfigAddr to set
    function testFuzz_property(address admin, address candidate) public {
        // keep admin non-zero (practical) but otherwise wide
        vm.assume(admin != address(0));

        // deploy a mock lrtConfig that recognizes `admin` as DEFAULT_ADMIN_ROLE
        MockLRTConfig mock = new MockLRTConfig(admin);

        // initialize c with the mock's address so that admin has the admin role
        // initialize uses initializer modifier; call from any address is fine here
        vm.prank(admin);
        c.initialize(address(mock));

        // Now admin is admin per mock. We will have admin call updateLRTConfig with fuzzed candidate.
        // The reference contract calls UtilLib.checkNonZeroAddress(candidate) which reverts when candidate==address(0).
        // The mutant removed that check and will accept address(0). Therefore the universal property:
        //   calling updateLRTConfig with candidate == address(0) MUST revert on the reference for any admin.
        // We assert that calling updateLRTConfig(candidate) reverts when candidate==address(0).
        // To obey the test harness rules we perform the call in try/catch and assert on the boolean ok.

        bool ok;
        vm.prank(admin);
        try c.updateLRTConfig(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: reference must revert when candidate is zero, i.e. ok == false if candidate==address(0).
        // Conversely, for non-zero candidate the reference may succeed; we only require the universal rule for zero.
        if (candidate == address(0)) {
            assertTrue(!ok);
        } else {
            // when candidate != zero, both reference and mutant may accept; ensure we don't make test fail spuriously
            assertTrue(ok);
        }
    }
}

