// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the admin caller address; the rule: when an LRT admin calls updateLRTConfig(address(0)),
    // the correct contract must revert (due to non-zero check), while the mutant (removed check) will succeed.
    function testFuzz_property(address admin) public {
        // bound admin to non-zero so it can plausibly be an admin (we will treat any address as candidate admin)
        // but keep broad: allow zero too — vm.assume not used to avoid excluding cases
        // We need to call updateLRTConfig as 'admin'. The onlyLRTAdmin modifier checks IAccessControl on lrtConfig
        // which is initially zero; however to reach the modifier's check we must set c.lrtConfig to a contract
        // that treats 'admin' as having the admin role. We'll deploy a tiny fake AccessControl that returns true
        // for hasRole(DEFAULT_ADMIN_ROLE, admin). Then set c.updateLRTConfig to that contract via initialize.

        // Deploy a mock ILRTConfig that has isSupportedAsset etc as stubs and acts as an AccessControl returning true
        MockLRTConfig mock = new MockLRTConfig(admin);
        // initialize c with mock as lrtConfig so that admin is considered LRT admin
        // initialize is external and uses initializer modifier; call it from any address
        c.initialize(address(mock));

        bool ok;
        try c.updateLRTConfig(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C enforces non-zero check and therefore updateLRTConfig(address(0)) MUST revert -> ok == false
        // The mutant removed the check and will set lrtConfig to zero and succeed -> ok == true for some input (admin)
        assertTrue(!ok);
    }
}

// Minimal mock implementing the parts required: acts as ILRTConfig and AccessControl for LRT admin check.
contract MockLRTConfig {
    address public adminToApprove;
    constructor(address admin_) {
        adminToApprove = admin_;
    }
    // mimic IAccessControl.hasRole: return true when checking DEFAULT_ADMIN_ROLE (0x00) for adminToApprove
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == adminToApprove;
    }
    // required stubs used by C: depositLimitByAsset, getContract, rsETH, isSupportedAsset
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function getContract(bytes32) external view returns (address) { return address(this); }
    function rsETH() external view returns (address) { return address(this); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
}

