pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MockLRTConfig is ILRTConfig {
    // minimal stub implementing the functions used by C contract
    address public override rsETH;
    mapping(address => uint256) public depositLimit;
    mapping(bytes32 => address) public contracts;
    mapping(address => address) public priceOracle;

    constructor(address _rsETH) {
        rsETH = _rsETH;
    }

    function setDepositLimit(address asset, uint256 limit) external {
        depositLimit[asset] = limit;
    }

    function setContract(bytes32 id, address addr) external {
        contracts[id] = addr;
    }

    function getContract(bytes32 contractId) external view override returns (address) {
        return contracts[contractId];
    }

    function rsETH() external view override returns (address) {
        return rsETH;
    }

    function assetStrategy(address) external pure override returns (address) { return address(0); }
    function isSupportedAsset(address) external pure override returns (bool) { return true; }
    function getLSTToken(bytes32) external pure override returns (address) { return address(0); }
    function getSupportedAssetList() external pure override returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address asset) external view override returns (uint256) { return depositLimit[asset]; }
}

// Minimal IERC20 used by MockRSETH
interface IERC20Minimal {
    function mint(address,uint256) external;
}

contract MockRSETH is IERC20Minimal {
    mapping(address => uint256) public balanceOf;
    function mint(address account, uint256 amount) external override {
        balanceOf[account] += amount;
    }
}

contract InvMutTest is Test {
    C c;
    MockLRTConfig mockConfig;
    MockRSETH mockRseth;

    function setUp() public {
        c = new C();
        mockRseth = new MockRSETH();
        mockConfig = new MockLRTConfig(address(mockRseth));
        // make the test msg.sender an admin in the mock by making hasRole return true via IAccessControl shim
        // Since C's onlyLRTAdmin calls IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
        // and our MockLRTConfig does not implement IAccessControl, but the call is external; to satisfy onlyLRTAdmin
        // we will deploy a tiny delegator that implements hasRole and forwards to our MockLRTConfig address for storage
    }

    // Small adapter implementing IAccessControl to allow our test address to be treated as admin
    contract Adminable is Test {
        mapping(bytes32 => mapping(address => bool)) public roles;
        function setRole(bytes32 role, address who, bool v) external {
            roles[role][who] = v;
        }
        function hasRole(bytes32 role, address account) external view returns (bool) {
            return roles[role][account];
        }
        function getRoleAdmin(bytes32) external pure returns (bytes32) { return bytes32(0); }
        function grantRole(bytes32, address) external {}
        function revokeRole(bytes32, address) external {}
        function renounceRole(bytes32, address) external {}
    }
}
